"/us/en/foot-and-ankle/procedures/ankle-distraction": {"template":"procedure-detail","metadata":{"title":"Ankle Distraction","pageTitle":null,"description":"A distraction arthroplasty stretches the ankle joint apart over a period of time. This effectively unloads the joint, allowing it to heal. An ankle distraction arthroplasty is most commonly used for patients with ankle arthritis without deformity.","image":"/content/dam/stryker/foot-and-ankle/procedures/Ankle-Distraction/Images/Ankle_AnkleDistraction.jpg","imageAlt":null,"tags":["stryker:business-unit/foot-and-ankle","stryker:specialty/ankle-foot-and-ankle","stryker:portfolio/orthopaedics","stryker:content-type/procedure","stryker:procedure/foot-and-ankle/-ankle-distraction","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2019-07-08T20:52:28.000Z","contentID":"OT-AWI-8, 07-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/foot-and-ankle/procedures/ankle-fracture": {"template":"procedure-detail","metadata":{"title":"Ankle Fracture","pageTitle":null,"description":"Ankle fractures are one of the most common fractures to occur. These can involve the lateral malleolus (fibula), medial malleolus, and/or the posterior malleolus. The syndesmosis may also be involved. Ankle fractures can also involve the articular surface of the tibia, known as pilon fractures. To provide stability and allow for an anatomic reduction, some of these fractures are treated surgically.","image":"/content/dam/stryker/foot-and-ankle/procedures/Ankle-Fracture/Images/Ankle_AnklePilonFracture.jpg","imageAlt":null,"tags":["stryker:procedure/foot-and-ankle/ankle-fracture","stryker:business-unit/foot-and-ankle","stryker:specialty/ankle-foot-and-ankle","stryker:portfolio/orthopaedics","stryker:content-type/procedure","stryker:content-type/hcp_content"],"originallyPublished":"2023-02-06T21:42:53.000Z","lastPublished":"2024-11-12T21:42:53.000Z","contentID":"OT-AWI-9, 07-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/foot-and-ankle/procedures/brachymetatarsia": {"template":"procedure-detail","metadata":{"title":"Brachymetatarsia","pageTitle":null,"description":"The treatment of brachymetatarsia involves lengthening of a short, or hypoplastic, metatarsal.","image":"/content/dam/stryker/foot-and-ankle/procedures/Brachymetatarsia/Images/Forefoot_Brachymetatarsia.jpg","imageAlt":null,"tags":["stryker:business-unit/foot-and-ankle","stryker:portfolio/orthopaedics","stryker:content-type/procedure","stryker:specialty/forefoot","stryker:procedure/foot-and-ankle/brachymetatarsia","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2019-07-08T20:52:28.000Z","contentID":"OT-AWI-10, 07-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/foot-and-ankle/procedures/bunionette--tailor-s-bunion-": {"template":"procedure-detail","metadata":{"title":"Bunionette (Tailor's Bunion)","pageTitle":null,"description":"A bunionette is an abnormal protuberance on the lateral side of the fifth toe. Surgical treatment can require a corrective osteotomy.","image":"/content/dam/stryker/foot-and-ankle/procedures/Bunionette--Tailor-s-bunion-/Images/Forefoot_Bunionette.jpg","imageAlt":null,"tags":["stryker:business-unit/foot-and-ankle","stryker:portfolio/orthopaedics","stryker:content-type/procedure","stryker:specialty/forefoot","stryker:procedure/foot-and-ankle/bunionette-(tailor-s-bunion)","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2019-07-08T20:52:27.000Z","contentID":"OT-AWI-11, 07-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/foot-and-ankle/procedures/calcaneal-fracture": {"template":"procedure-detail","metadata":{"title":"Calcaneal Fracture","pageTitle":null,"description":"Fractures of the calcaneus – or heel bone – most often occur after falls from heights or motor vehicle collisions. Treatment of calcaneal fractures may require surgery.","image":"/content/dam/stryker/foot-and-ankle/procedures/Calcaneal-Fracture/Images/Hindfoot_CalcanealFracture.jpg","imageAlt":null,"tags":["stryker:procedure/foot-and-ankle/calcaneal-fracture","stryker:business-unit/foot-and-ankle","stryker:specialty/hindfoot","stryker:portfolio/orthopaedics","stryker:content-type/procedure","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2020-09-14T17:59:21.000Z","contentID":"OT-AWI-12, 07-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/foot-and-ankle/procedures/calcaneal-sliding-osteotomy": {"template":"procedure-detail","metadata":{"title":"Calcaneal Sliding Osteotomy","pageTitle":null,"description":"Calcaneal sliding osteotomies are commonly performed to correct hindfoot deformity. The calcaneus can be translated in either a medial or lateral direction.","image":"/content/dam/stryker/foot-and-ankle/procedures/Calcaneal-Sliding-Osteotomy/Images/Hindfoot_CalcanealSlidingOst.jpg","imageAlt":null,"tags":["stryker:business-unit/foot-and-ankle","stryker:specialty/hindfoot","stryker:procedure/foot-and-ankle/calcaneal-sliding-osteotomy","stryker:portfolio/orthopaedics","stryker:content-type/procedure","stryker:content-type/hcp_content"],"originallyPublished":"2023-02-06T20:56:31.000Z","lastPublished":"2024-12-27T20:56:31.000Z","contentID":"OT-AWI-13, 07-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/foot-and-ankle/procedures/calcaneo-cuboid-arthrodesis": {"template":"procedure-detail","metadata":{"title":"Calcaneo-cuboid Arthrodesis","pageTitle":null,"description":"Calcaneo-cuboid fusions are performed to relieve pain from arthritic or unstable joints, or as part of a lateral column lengthening procedure.","image":"/content/dam/stryker/foot-and-ankle/procedures/Calcaneo-cuboid-Arthrodesis/Images/Hindfoot_Calcaneo-cuboid_arthro.jpg","imageAlt":null,"tags":["stryker:business-unit/foot-and-ankle","stryker:specialty/hindfoot","stryker:procedure/foot-and-ankle/calcaneo-cuboid-arthrodesis","stryker:portfolio/orthopaedics","stryker:content-type/procedure","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2020-09-14T17:59:21.000Z","contentID":"OT-AWI-14, 07-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
