"/us/en/foot-and-ankle/procedures/metatarsal-shortening--weil--osteotomy": {"template":"procedure-detail","metadata":{"title":"Metatarsal Shortening (Weil) Osteotomy","pageTitle":null,"description":"Metatarsal shortening osteotomies are often used to correct angular deformities or toe dislocations, most commonly seen in hammertoes or claw toes.","image":"/content/dam/stryker/foot-and-ankle/procedures/Metatarsal-Shortening--Weil--Osteotomy/Images/Forefoot_MetatarsalShortening.jpg","imageAlt":null,"tags":["stryker:portfolio/orthopaedics","stryker:content-type/procedure","stryker:business-unit/foot-and-ankle","stryker:specialty/forefoot","stryker:procedure/foot-and-ankle/metatarsal-shortening-(weil)-osteotomy","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2019-07-08T20:52:28.000Z","contentID":"OT-AWI-27, 07-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
